export const DASHBOARD_ALLOWED_NEXT_PATHS = [
    '/api/slack/connect',
    '/api/end-user-auth/deployment',
    '/api/cli/oauth/authorize',
    '/api/desktop/oauth/authorize',
    '/api/admin-mcp/oauth/authorize',
    '/api/workos/connect/login',
    '/api/bitbucket-oauth/callback',
    '/slack/connect',
    '/teams/connect',
    '/editor',
    '/onboarding',
    '/agent-claim',
];
const DASHBOARD_ALLOWED_NEXT_PATH_PREFIXES = ['/api/slack/connect'];
const SAFE_PATH_SEGMENT = /^[A-Za-z0-9_-]+$/;
const PROJECT_NEXT_PATH_PATTERN = /^\/[^/?#]+\/[^/?#]+(?:\/~(?:\/[^?#]+)?|\/editor(?:\/[^/?#]+(?:\/~(?:\/[^?#]+)?)?)?|\/activity)?$/;
const MAX_NEXT_DEPTH = 4;
const PROJECT_SECTION_NEXT_PATHS = ['settings', 'analytics', 'products', 'publishes'];
function isProjectSectionNextPath(pathname) {
    const [org, project, section, ...rest] = pathname.split('/').slice(1);
    if (!org || !project || !section || org === 'api')
        return false;
    return (PROJECT_SECTION_NEXT_PATHS.includes(section) &&
        rest.every((segment) => SAFE_PATH_SEGMENT.test(segment)));
}
export const validateDashboardRedirect = (next) => {
    try {
        const baseUrl = 'https://example.com';
        for (let depth = 0; depth <= MAX_NEXT_DEPTH; depth++) {
            const url = new URL(next, baseUrl);
            const normalizedNext = `${url.pathname}${url.search}${url.hash}`;
            if (url.origin !== baseUrl || normalizedNext !== next)
                return false;
            const hasAllowedChild = DASHBOARD_ALLOWED_NEXT_PATH_PREFIXES.some((prefix) => url.pathname.startsWith(`${prefix}/`) &&
                SAFE_PATH_SEGMENT.test(url.pathname.slice(prefix.length + 1)));
            if (!DASHBOARD_ALLOWED_NEXT_PATHS.includes(url.pathname) &&
                !hasAllowedChild &&
                !PROJECT_NEXT_PATH_PATTERN.test(url.pathname) &&
                !isProjectSectionNextPath(url.pathname))
                return false;
            if (url.pathname !== '/onboarding')
                return true;
            const continuations = url.searchParams.getAll('next');
            if (continuations.length === 0)
                return true;
            const [continuation] = continuations;
            if (continuations.length !== 1 || !continuation)
                return false;
            next = continuation;
        }
        return false;
    }
    catch (_a) {
        return false;
    }
};
